#!/usr/bin/env python3
"""Build six static, script-free pages using only the Python standard library."""
from pathlib import Path
import shutil
from html import escape
ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'dist'
REPO = 'https://github.com/Hanyan179/Tracebook'
def link(path, text, cls=''):
    return f'<a class="{cls}" href="{REPO}{path}">{text}<span aria-hidden="true"> ↗</span></a>'
def badge(text): return f'<span class="status">{text}</span>'
def section(n, title, body, status, extra=''):
    return f'<section class="chapter" id="step-{n}"><div class="chapter-label">{n:02d} / {status}</div><div><h2>{title}</h2><p>{body}</p>{extra}</div></section>'
COPY = {
'zh': dict(lang='zh-CN', name='迹库', home='产品', start='开始使用', privacy='隐私说明', switch='English', skip='跳到主要内容', stage='开源 · 开发中', title='把留下的信息，<br>整理成自己的记忆。', intro='随手留下的语音、已有文字和本地工具输入，都值得有一个自己的归处。迹库保留来源，让每一次回看，都能找到依据。', source='查看源码', build='构建指南', note='当前为源码开发版，尚无已签名、公证的安装包。', roles=[('iPhone','随手记录','录音、回放与资料入口。'),('Apple Watch','抬腕留下','把想法先保存，再交给后续整理。'),('Mac','汇集与阅读','管理来源、检索原文、审阅记忆。')], journey='从一个片刻，到有依据的记忆。', journey_intro='不是一键完成的承诺，而是一条逐步做可靠的路径。以下标记区分当前能力与仍在开发的部分。', available='已有基础', developing='开发中', footer='你的资料，你的来处。', nav='主导航', footnav='相关链接', roadmap='迭代清单', contribute='参与开发', license='MIT 许可', updated='能力依据：2026 年 10 月 22 日公开源码。', project='一个仍在认真生长的开源项目。', projectbody='从源码了解它，从具体问题参与它。我们先把导入、来源与确认做可靠，再扩展自动整理的边界。', privacycta='了解资料与隐私', sourcecode='公开源码', storylabel='流程说明 · 非运行画面', timeline=[('留下','语音 / 文字 / 工具输入'),('归集','保留时间、来源与版本'),('核对','从检索结果回到原文')]),
'en': dict(lang='en', name='Tracebook', home='Product', start='Get started', privacy='Privacy', switch='中文', skip='Skip to content', stage='Open source · In development', title='Keep the traces.<br>Make them your memory.', intro='A place of your own for voice notes, existing text and local tool inputs. Tracebook keeps the source close, so you can always return to what was actually said.', source='View source', build='Build guide', note='Source-only development release. No signed, notarized installer is available.', roles=[('iPhone','Capture a thought','Record, play back and bring material in.'),('Apple Watch','Leave a trace','Save the moment for later organization.'),('Mac','Gather and read','Manage sources, retrieve text and review memories.')], journey='From a passing moment to a grounded memory.', journey_intro='A path we are making reliable, not a promise of one-click automation. Each stage distinguishes existing foundations from work still in progress.', available='Existing foundation', developing='In development', footer='Your material. Your own record.', nav='Main navigation', footnav='Related links', roadmap='Roadmap', contribute='Contribute', license='MIT license', updated='Capabilities checked against public source on 22 October 2026.', project='Open source, and still taking shape.', projectbody='Explore the source and contribute to a concrete problem. Reliable imports, sources and confirmation come before broader automation.', privacycta='Read about data and privacy', sourcecode='Public source', storylabel='Workflow illustration · Not an app screenshot', timeline=[('Capture','Voice / text / tool inputs'),('Gather','Keep time, source and version'),('Check','Return from results to the original')])}
def home(l, c):
    roles=''.join(f'<li><span class="device">{a}</span><h3>{b}</h3><p>{d}</p></li>' for a,b,d in c['roles'])
    timeline=''.join(f'<li><span class="dot"></span><div><strong>{a}</strong><p>{b}</p></div></li>' for a,b in c['timeline'])
    top=f'''<section class="hero"><div><p class="eyebrow"><span class="live-dot"></span>{c['stage']}</p><h1>{c['title']}</h1><p class="intro">{c['intro']}</p><div class="actions">{link('',c['source'],'button primary')}<a class="button secondary" href="start.html">{c['build']} <span aria-hidden="true">→</span></a></div><p class="small release">{c['note']}</p></div><aside class="trace"><img src="assets/brand-mark.png" alt="" width="150" height="150"><ol>{timeline}</ol><p class="small">{c['storylabel']}</p></aside></section><ul class="devices">{roles}</ul><div class="section-heading"><p class="eyebrow">TRACE / MEMORY</p><h2>{c['journey']}</h2><p>{c['journey_intro']}</p></div>'''
    if l=='zh':
        chapters=[
('先留下，再慢慢整理。','手机与手表已有录音、暂停、保存和回放。电脑可导入 UTF-8 文字文件（.md、.markdown、.txt、.text，单份不超过 2 MB），以及已适配的 Codex、Claude Code 本地会话格式。不是任意文档解析器。','已有基础','<p class="detail">系统快捷动作、操作按钮、轻点背面等入口需要系统绑定；部分入口与手表操作尚未完成真机验收。不承诺任意后台触发。真实自动转写仍在开发。</p>'),
('不同来处，保留各自的上下文。','先预览，再确认导入。资料汇集保留来源、时间与版本；已有导出聊天的 JSON / ZIP 导入入口，区分用户和助手。导入不等于把每一句话认作你的事实。','已有基础','<p class="detail">工具输入只覆盖已适配格式，不复制登录文件与完整配置。PDF、Office 文档和扫描件解析仍待逐种适配。</p>'),
('记忆，需要你来确认。','已有带来源的候选确认流程，当前候选仍引用录音。统一文字资料、工具输入与录音的记忆整理，以及更正、停用与恢复，仍在开发。','部分已有 · 仍在开发','<div class="principle"><span>原文 ≠ 模型建议 ≠ 已确认记忆</span><p>这是产品坚持的分层方向，不是所有来源已打通的演示。</p></div>'),
('找到了，也能回去核对。','当前资料对话返回本地检索结果、来源片段，并支持原文阅读。它现在不会生成模型回答，不把检索片段包装成已经验证的结论。','已有基础','<p class="detail">每日文字分析已有模型适配器、引用与失败保护，但真实模型质量尚未验收。引用存在，不代表推断一定成立。</p>'),
('文件在自己手里，选择也一样。','资料保存到用户选择的文件夹。保留来源历史，人工修改发生冲突时另存版本；文字可便携导出，排除凭证与原音。','已有基础','<p class="detail">文字导出不是完整备份或自动恢复包，请独立备份真实资料。已有传输队列、校验、回执与资料夹交换；真实异地云同步和后台链路仍待验收。</p>')]
    else:
        chapters=[
('Capture now. Organize in your own time.','Phone and watch recording, pause, save and playback are implemented. On Mac, import UTF-8 text (.md, .markdown, .txt, .text; up to 2 MB each) and supported local session formats from Codex and Claude Code. This is not a universal document parser.','Existing foundation','<p class="detail">System shortcuts, Action Button and Back Tap need system configuration. Some entry points and watch interactions still need real-device validation. Arbitrary background triggers are not promised. Real automatic transcription is still in development.</p>'),
('Different sources. Their context intact.','Preview before confirming an import. Keep sources, dates and versions together. An import path for exported JSON / ZIP chats distinguishes user and assistant. Importing a statement does not make it a fact about you.','Existing foundation','<p class="detail">Tool imports cover adapted formats only, without copying login files or full configurations. PDF, Office documents and scans still need format-specific support.</p>'),
('A memory should be yours to confirm.','A source-backed candidate confirmation flow exists, currently referencing recordings. Unified memory organization across documents, tool inputs and recordings, with correction, deactivation and restoration, is still in development.','Partial · In development','<div class="principle"><span>Original ≠ Model suggestion ≠ Confirmed memory</span><p>A product principle, not a demonstration of a completed multi-source pipeline.</p></div>'),
('Find it. Then check the original.','The current conversation view returns local search results and source excerpts, with access to the original text. It does not generate model answers or turn retrieved fragments into verified conclusions.','Existing foundation','<p class="detail">Daily text analysis has a configurable model adapter, citations and failure safeguards. Real-model quality is not yet validated. A citation alone does not prove an inference.</p>'),
('Your files. Your choice.','Material lives in a folder you choose. Source history is retained, and conflicts with manual edits create another version. Portable text export excludes credentials and original audio.','Existing foundation','<p class="detail">Text export is not a full backup or automatic restore package. Back up real material separately. Transfer queues, checksums, receipts and folder exchange exist; real remote cloud sync and background operation still need validation.</p>')]
    body=''.join(section(i,*x) for i,x in enumerate(chapters,1))
    return top+body+f'''<section class="open-source"><p class="eyebrow">OPEN SOURCE / MIT</p><h2>{c['project']}</h2><p>{c['projectbody']}</p><div class="actions">{link('/blob/main/ROADMAP.md',c['roadmap'],'text-link')}{link('/blob/main/CONTRIBUTING.md',c['contribute'],'text-link')}<a class="text-link" href="privacy.html">{c['privacycta']} →</a></div></section>'''
def start(l,c):
    if l=='zh':
        lead='从源码开始，先了解边界。'; desc='迹库目前面向愿意自行构建、检查与参与的使用者。没有应用商店下载，也没有即装即用的完整自动记忆服务。'
        blocks=[('01','准备构建环境','原生客户端需要 Mac、Xcode 26 或以上及手机与手表平台组件。最低部署目标为 macOS 14、iOS 18、watchOS 11；不代表每个系统版本均已实测。当前桌面内置节点依赖系统 Python 3。'),('02','按公开指南构建','阅读仓库开发说明后，克隆源码、准备节点运行时并生成工程。桌面与模拟器可以无个人签名构建；真机运行需要自己的签名设置。不要提交个人签名或设备信息。'),('03','用合成资料先试一遍','先使用少量非敏感测试文字，预览后确认导入，再检查检索结果、来源版本和导出。不要一开始就把唯一的真实资料交给开发版。'),('04','按需配置服务','导入不会自动发送给模型。模型处理取决于你选择的提供商、配置与启用，自备服务可能收费。真实自动转写未完成，文字模型配置不等于已启用语音转写。')]
        limits='开始前，请知道'; items=['目前没有已签名、公证的安装包，普通用户安装体验仍在完善。','资料对话是检索，不生成回答。统一多来源记忆和修订仍在开发。','真实模型质量、异地云同步和后台链路尚未完成验收。','导出不是完整恢复。请为真实资料保留独立备份。']; guide='打开完整构建指南'; more='开发说明是客户端构建的维护入口。此静态官网不运行资料节点，也不接收你的文件。'
    else:
        lead='Start with source. Know the boundaries.'; desc='Tracebook is currently for people willing to build, inspect and contribute. There is no App Store download or ready-to-install complete automatic memory service.'
        blocks=[('01','Prepare your build environment','Native clients require a Mac, Xcode 26 or later, and iPhone and watch platform components. Minimum targets are macOS 14, iOS 18 and watchOS 11, not a claim of testing on every version. The desktop node currently depends on system Python 3.'),('02','Follow the public build guide','Read the development guide, clone the source, prepare the node runtime and generate the project. Desktop and simulator builds can omit personal signing; physical devices require your own signing configuration. Never commit signing or device information.'),('03','Try synthetic material first','Start with a small amount of non-sensitive test text. Preview and confirm the import, then check search results, source versions and export. Do not entrust your only copy of real material to a development release.'),('04','Configure services deliberately','Import does not automatically send material to a model. Processing depends on the provider you choose, your configuration and activation. Your provider may charge fees. Real automatic transcription is unfinished; configuring a text model does not enable speech transcription.')]
        limits='Before you begin'; items=['No signed, notarized installer is available. Everyday installation is still being developed.','Conversation retrieves sources, not generated answers. Unified multi-source memory and revision remain in development.','Real-model quality, remote cloud sync and background workflows are not fully validated.','Export is not full recovery. Keep a separate backup of real material.']; guide='Open the full build guide'; more='The development guide is the maintained source for client build instructions. This static website does not run a data node or receive your files.'
    return f'<div class="page-intro"><p class="eyebrow">GET STARTED</p><h1>{lead}</h1><p class="intro">{desc}</p></div><div class="reading">'+''.join(f'<section class="guide-step"><span class="number">{n}</span><div><h2>{h}</h2><p>{b}</p></div></section>' for n,h,b in blocks)+f'<div class="guide-cta">{link("/blob/main/docs/development.md",guide,"button primary")}<p class="small">{more}</p></div><section class="notice"><h2>{limits}</h2><ul>'+''.join(f'<li>{i}</li>' for i in items)+f'</ul>{link("/blob/main/ROADMAP.md",c["roadmap"],"text-link")}</section></div>'
def privacy(l,c):
    if l=='zh':
        lead='资料归你，边界说清楚。'; desc='本地优先不意味着数据绝不会离开设备。了解网站、客户端、模型服务和外部读取分别做什么，再决定如何使用。'
        blocks=[('这个网站','本站是静态介绍页，不加入统计脚本、收集表单、账号、广告或追踪 Cookie。页面不上传个人资料。访问外部源码和文档链接时，目标网站按其自己的规则处理请求；未来托管服务也可能记录常规访问日志。'),('导入与原始来源','来源目录只读，先预览再确认。登录文件与完整配置不归档，但常见凭证过滤不能识别全部私人信息。导入不会自动发送给模型，也不会自动把他人发言或助手回答变成你的事实。'),('模型与费用','第三方模型处理取决于用户的配置与启用。启用处理前，应核对服务商、发送内容、保留政策与费用。语音和文字模型是不同角色；自备模型服务可能计费，项目不承诺免费模型服务。'),('文件、同步与备份','资料放在用户选择的文件夹。文字导出排除凭证与原音，不是完整备份恢复。使用同步资料夹时，相关资料会受你所选同步服务的规则约束。真实异地与后台同步链路仍待验收，不能把同步等同于备份。'),('外部读取与网络','节点默认只监听本机。外部只读凭证有独立范围、期限与撤销，新资料类型需要单独授权。局域网直连需明确启用；普通 HTTP 不加密，不应把节点直接暴露到公网。远程访问需要有效 HTTPS。'),('安全问题与开发状态','这是早期开发版本，不承诺生产环境安全认证。报告问题时只使用最小复现和合成数据，不公开真实录音、聊天、模型密钥、数据库或完整日志。')]; security='阅读完整安全说明'; report='私密报告安全问题'; date='本说明依据当前公开实现，不替代你所选服务商的隐私政策。'
    else:
        lead='Your material. Clear boundaries.'; desc='Local-first does not mean data can never leave a device. Understand the website, clients, model services and external access before choosing how to use them.'
        blocks=[('This website','This is a static information site, with no analytics scripts, collection forms, accounts, ads or tracking cookies. It does not upload personal material. External source and documentation links are handled under the destination’s own policies. A future hosting provider may keep ordinary access logs.'),('Imports and original sources','Source directories are read-only, with preview before confirmation. Login files and full configurations are not archived, but common credential filtering cannot detect all private information. Imports do not automatically go to a model or turn other people’s statements and assistant replies into facts about you.'),('Models and fees','Third-party model processing depends on your configuration and activation. Before enabling it, check the provider, content sent, retention policies and fees. Speech and text models have separate roles. Your chosen model provider may charge fees; the project does not promise free model services.'),('Files, sync and backup','Material lives in a folder you choose. Text export excludes credentials and original audio and is not a full backup or restore format. A sync folder is subject to your chosen sync provider’s policies. Real remote and background sync workflows still need validation. Sync is not backup.'),('External access and networking','The node listens locally by default. External read-only credentials have separate scopes, expiry and revocation; new material types need their own authorization. LAN access must be explicitly enabled. Plain HTTP is unencrypted; do not expose the node directly to the public internet. Remote access requires valid HTTPS.'),('Security and development status','This is an early development release, without a claim of production security certification. Report issues with a minimal reproduction and synthetic data. Do not publicly share real recordings, chats, model keys, databases or full logs.')]; security='Read the full security guidance'; report='Report a vulnerability privately'; date='This explanation reflects the public implementation, not a replacement for your chosen providers’ privacy policies.'
    return f'<div class="page-intro"><p class="eyebrow">PRIVACY & OWNERSHIP</p><h1>{lead}</h1><p class="intro">{desc}</p></div><div class="reading privacy-copy">'+''.join(f'<section><h2>{h}</h2><p>{b}</p></section>' for h,b in blocks)+f'<div class="actions">{link("/blob/main/SECURITY.md",security,"text-link")}{link("/security/advisories/new",report,"text-link")}</div><p class="small">{date}</p></div>'
def render(l,page):
    c=COPY[l]; other='en' if l=='zh' else 'zh'; filename={'home':'index.html','start':'start.html','privacy':'privacy.html'}[page]; prefix='../' if l=='en' else ''; langhref='../'+filename if l=='en' else 'en/'+filename
    body={'home':home,'start':start,'privacy':privacy}[page](l,c).replace('src="assets/',f'src="{prefix}assets/')
    nav=''.join(f'<a href="{f}"'+(' aria-current="page"' if k==page else '')+f'>{c[k]}</a>' for k,f in [('home','index.html'),('start','start.html'),('privacy','privacy.html')])
    return f'''<!doctype html>
<html lang="{c['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{escape(c['intro'],quote=True)}"><meta name="color-scheme" content="light"><title>{c[page]} · {c['name']}</title><link rel="icon" type="image/png" href="{prefix}assets/favicon.png"><link rel="stylesheet" href="{prefix}assets/style.css"><link rel="alternate" hreflang="{COPY[other]['lang']}" href="{langhref}"></head><body><a class="skip-link" href="#main">{c['skip']}</a><header class="header shell"><a class="brand" href="index.html"><img src="{prefix}assets/brand-mark.png" width="44" height="44" alt=""><span>{c['name']}<small>{'Tracebook' if l=='zh' else '迹库'}</small></span></a><nav aria-label="{c['nav']}">{nav}</nav><a class="language" href="{langhref}" lang="{COPY[other]['lang']}" hreflang="{COPY[other]['lang']}">{c['switch']} <span aria-hidden="true">↗</span></a></header><main id="main" class="shell" tabindex="-1">{body}</main><footer class="shell"><div><a class="brand" href="index.html"><img src="{prefix}assets/brand-mark.png" width="38" height="38" alt=""><span>{c['name']}</span></a><p>{c['footer']}</p></div><nav aria-label="{c['footnav']}">{link('',c['sourcecode'])}{link('/blob/main/ROADMAP.md',c['roadmap'])}{link('/blob/main/LICENSE',c['license'])}<a href="privacy.html">{c['privacy']}</a></nav><p class="small footer-note">{c['updated']}</p></footer></body></html>'''
def build():
    OUT.mkdir(exist_ok=True)
    shutil.copytree(ROOT/'assets',OUT/'assets',dirs_exist_ok=True)
    for l in COPY:
        folder=OUT/('en' if l=='en' else '')
        folder.mkdir(exist_ok=True)
        for p,f in [('home','index.html'),('start','start.html'),('privacy','privacy.html')]:
            (folder/f).write_text(render(l,p),encoding='utf-8')
    print('Built 6 static pages in website/dist (no network requests or dependencies).')
if __name__=='__main__': build()
